import com.example.lending.application.port.out.LoadLoanHistoryPort.LoanHistoryRow;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Loan;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.UUID;

@Service
@Transactional(readOnly = true)
public class GetLoanHistoryService implements GetLoanHistoryUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanHistoryPort loadLoanHistoryPort;

    public GetLoanHistoryService(LoadMemberPort loadMemberPort, LoadLoanHistoryPort loadLoanHistoryPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanHistoryPort = loadLoanHistoryPort;
    }

    @Override
    public List<LoanHistoryItem> getLoanHistory(UUID memberId) {
        loadMemberPort.loadMember(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));

        return loadLoanHistoryPort.loadLoanHistory(memberId).stream()
                .map(GetLoanHistoryService::toItem)
                .toList();
    }

    private static LoanHistoryItem toItem(LoanHistoryRow row) {
        Long lateFee = row.returnedAt() == null ? null : Loan.lateFeeOf(row.dueAt(), row.returnedAt());
        return new LoanHistoryItem(row.loanId(), row.title(), row.loanedAt(), row.returnedAt(), lateFee);
    }
}

