import com.example.lending.domain.LoanLimitExceededException;
import com.example.lending.domain.LoanNotFoundException;
import com.example.lending.domain.MemberAlreadyExistsException;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.MemberSuspendedException;
import com.example.lending.domain.ReservedForOtherException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class WebExceptionHandler {

    @ExceptionHandler(BookAlreadyOnLoanException.class)
    public ProblemDetail handleAlreadyOnLoan(BookAlreadyOnLoanException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(BookOnLoanException.class)
    public ResponseEntity<ErrorBody> handleBookOnLoan(BookOnLoanException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("BOOK_ON_LOAN"));
    }

    @ExceptionHandler(BookDiscardedException.class)
    public ResponseEntity<ErrorBody> handleBookDiscarded(BookDiscardedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("BOOK_DISCARDED"));
    }

    @ExceptionHandler(BookAvailableException.class)
    public ResponseEntity<ErrorBody> handleBookAvailable(BookAvailableException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("BOOK_AVAILABLE"));
    }

    @ExceptionHandler(ReservedForOtherException.class)
    public ResponseEntity<ErrorBody> handleReservedForOther(ReservedForOtherException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("RESERVED_FOR_OTHER"));
    }

    @ExceptionHandler(AlreadyReservedException.class)
    public ResponseEntity<ErrorBody> handleAlreadyReserved(AlreadyReservedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("ALREADY_RESERVED"));
    }

    @ExceptionHandler(LoanLimitExceededException.class)
    public ResponseEntity<ErrorBody> handleLoanLimitExceeded(LoanLimitExceededException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("LOAN_LIMIT_EXCEEDED"));
    }

    @ExceptionHandler(MemberSuspendedException.class)
    public ResponseEntity<ErrorBody> handleMemberSuspended(MemberSuspendedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("MEMBER_SUSPENDED"));
    }

    @ExceptionHandler(CreditRejectedException.class)
    public ResponseEntity<ErrorBody> handleCreditRejected(CreditRejectedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("CREDIT_REJECTED"));
    }

    @ExceptionHandler(CreditCheckUnavailableException.class)
    public ResponseEntity<ErrorBody> handleCreditCheckUnavailable(CreditCheckUnavailableException e) {
        return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(new ErrorBody("CREDIT_CHECK_UNAVAILABLE"));
    }

    @ExceptionHandler(LoanAlreadyReturnedException.class)
    public ResponseEntity<ErrorBody> handleAlreadyReturned(LoanAlreadyReturnedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("ALREADY_RETURNED"));
    }

    @ExceptionHandler(LoanNotFoundException.class)
    public ProblemDetail handleLoanNotFound(LoanNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(BookNotFoundException.class)
    public ProblemDetail handleNotFound(BookNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(MemberAlreadyExistsException.class)
    public ResponseEntity<ErrorBody> handleMemberAlreadyExists(MemberAlreadyExistsException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorBody("MEMBER_ALREADY_EXISTS"));
    }

    @ExceptionHandler(MemberNotFoundException.class)
    public ProblemDetail handleMemberNotFound(MemberNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleInvalidInput(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}
