import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;
import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.ReservationQueue;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;

@Service
@Transactional
public class LoanBookService implements LoanBookUseCase {

    private final LoadMemberPort loadMemberPort;
    private final CountActiveLoansPort countActiveLoansPort;
    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final SaveLoanPort saveLoanPort;
    private final LoadReservationsPort loadReservationsPort;
    private final RemoveReservationPort removeReservationPort;
    private final CheckCreditPort checkCreditPort;
    private final SaveAuditLogPort saveAuditLogPort;

    public LoanBookService(LoadMemberPort loadMemberPort,
                           CountActiveLoansPort countActiveLoansPort,
                           LoadBookPort loadBookPort,
                           SaveBookPort saveBookPort,
                           SaveLoanPort saveLoanPort,
                           LoadReservationsPort loadReservationsPort,
                           RemoveReservationPort removeReservationPort,
                           CheckCreditPort checkCreditPort,
                           SaveAuditLogPort saveAuditLogPort) {
        this.loadMemberPort = loadMemberPort;
        this.countActiveLoansPort = countActiveLoansPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.saveLoanPort = saveLoanPort;
        this.loadReservationsPort = loadReservationsPort;
        this.removeReservationPort = removeReservationPort;
        this.checkCreditPort = checkCreditPort;
        this.saveAuditLogPort = saveAuditLogPort;
    }

    @Override
    public Loan loanBook(LoanBookCommand command) {
        Member member = loadMemberPort.loadMemberForUpdate(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        member.checkCanBorrow(countActiveLoansPort.countActiveLoans(member.getId()));

        Book book = loadBookPort.loadBookForUpdate(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        LocalDate loanedAt = command.loanedAt() != null ? command.loanedAt() : LocalDate.now();
        ReservationQueue reservations = new ReservationQueue(loadReservationsPort.loadReservations(book.getId()));
        // 신용조회는 대출 직전에 한다. 거절되면 loanTo 가 예외를 던져 책과 대출 기록은 저장되지 않는다
        CreditCheck creditCheck = checkCreditPort.checkCredit(member.getId(), member.getName());
        Loan loan = book.loanTo(member.getId(), loanedAt, reservations, creditCheck);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        saveAuditLogPort.saveAuditLog(AuditLog.now(AuditAction.LOAN, loan.getId(), member.getId()));
        // loanTo 를 통과했다면 맨 앞 예약자가 이 회원이므로, 그 예약은 이번 대출로 소진된다
        reservations.first().ifPresent(first -> removeReservationPort.removeReservation(first.getId()));
        return loan;
    }
}
